// probe_trans.cu — dump ldmatrix .trans fragment layout for an 8x8 bf16 matrix
#include <cuda_bf16.h>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <math.h>

__device__ __forceinline__ uint32_t smem_u32(const void* p) {
    return static_cast<uint32_t>(__cvta_generic_to_shared(p));
}
__device__ __forceinline__ void ldmatrix_x2_t(uint32_t r[2], uint32_t addr) {
    asm volatile("ldmatrix.sync.aligned.m8n8.x2.trans.shared.b16 {%0,%1}, [%2];\n"
        : "=r"(r[0]), "=r"(r[1]) : "r"(addr));
}

__global__ void probe_kernel(float* err_out) {
    __shared__ __nv_bfloat16 M[16][16];  // 2 matrices of 8x8: rows 0-7 (M0), 8-15 (M1)
    const int lane = threadIdx.x;
    for (int i = lane; i < 16 * 16; i += 32) {
        int r = i / 16, c = i % 16;
        M[r][c] = __float2bfloat16((float)(r * 16 + c));  // M0[r][c] = r*16+c
    }
    __syncthreads();

    // lane provides address: lanes 0-7 -> M0 rows 0-7; lanes 8-15 -> M1 rows 0-7.
    // M0 = rows 0..7 of M, M1 = rows 8..15 of M.
    int m = lane >> 3;
    int r = (m & 1) ? 8 : 0;
    uint32_t addr = smem_u32(&M[r + (lane & 7)][0]);
    uint32_t frag[2];
    ldmatrix_x2_t(frag, addr);

    // Expected (interp A): reg0 = {M[2t][g], M[2t+1][g]}, reg1 = {M[8+2t][g], M[8+2t+1][g]}
    // where g = lane>>2, t = lane&3. M matrix index: rows 2t,2t+1 in M0 -> M[2t][g]... 
    // NOTE: with .trans, thread i gets M^T[i/4][(i%4)*2 .. +1] = M[(i%4)*2 .. +1][i/4] of ITS matrix.
    const int g = lane >> 2, t = lane & 3;
    int row0 = (m & 1) ? 8 : 0;
    uint16_t lo0 = frag[0] & 0xffff, hi0 = frag[0] >> 16;
    uint16_t lo1 = frag[1] & 0xffff, hi1 = frag[1] >> 16;
    float f_lo0 = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&lo0));
    float f_hi0 = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&hi0));
    float f_lo1 = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&lo1));
    float f_hi1 = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&hi1));
    printf("lane %2d: reg0={%6.1f,%6.1f} reg1={%6.1f,%6.1f} | expectA reg0={M[%d][%d]=%4.1f, M[%d][%d]=%4.1f}\n",
