           row0+2*t, g, (float)((row0+2*t)*16+g), row0+2*t+1, g, (float)((row0+2*t+1)*16+g));
}

int main() {
    probe_kernel<<<1, 32>>>();
    cudaDeviceSynchronize();
    return 0;
}

