    const int lane = threadIdx.x;
    for (int i = lane; i < 16 * 128; i += 32) {
        int r = i / 128, c = i % 128;
        sV[r][c] = __float2bfloat16((r * 11 + c * 13 + 2) * 0.01f);
    }
    __syncthreads();

    const int g = lane >> 2, t = lane & 3;
    // A = identity 16x16 (k-chunk 0), O(16x8) = A(16x16) x V(16x8)
    // A[r][k] = (r==k) ? 1 : 0. A fragment: reg0={A[g][2t],A[g][2t+1]}, reg1={A[g+8][2t],A[g+8][2t+1]},
    // reg2={A[g][2t+8],A[g][2t+9]}, reg3={A[g+8][2t+8],A[g+8][2t+9]}
    uint32_t a[4];
    auto idpair = [&](int r0, int c0, int c1) {
        float x = (r0 == c0) ? 1.f : 0.f;
        float y = (r0 == c1) ? 1.f : 0.f;
        return (uint32_t)__bfloat16_as_ushort(__float2bfloat16(x)) |
               ((uint32_t)__bfloat16_as_ushort(__float2bfloat16(y)) << 16);
    };
    a[0] = idpair(g, 2*t, 2*t+1);
    a[1] = idpair(g+8, 2*t, 2*t+1);
    a[2] = idpair(g, 2*t+8, 2*t+9);
    a[3] = idpair(g+8, 2*t+8, 2*t+9);

    // B = V rows 0..15, cols 0..7 (head chunk 0)
    int m = lane >> 3;
    uint32_t addr = smem_u32(&sV[((m & 1) ? 8 : 0) + (lane & 7)][0]);
    uint32_t b[2];
    ldmatrix_x2_t(b, addr);

    float c[4] = {0, 0, 0, 0};
    float d[4];
    mma_m16n8k16(d, a, b, c);

    // Expected: O[r][n] = V[r][n] for r in 0..15, n in 0..7 (A=I)
    // d0,d1 = row g, cols 2t, 2t+1; d2,d3 = row g+8
    float exp0 = __bfloat162float(sV[g][2*t]);
    float exp1 = __bfloat162float(sV[g][2*t+1]);
    float exp2 = __bfloat162float(sV[g+8][2*t]);
    float exp3 = __bfloat162float(sV[g+8][2*t+1]);
    float err = fmaxf(fabsf(d[0]-exp0), fmaxf(fabsf(d[1]-exp1), fmaxf(fabsf(d[2]-exp2), fabsf(d[3]-exp3))));
    if (err > 1e-3f && lane < 8)
        printf("lane %d: d={%f,%f,%f,%f} exp={%f,%f,%f,%f} b={%08x,%08x}\n",
               lane, d[0], d[1], d[2], d[3], exp0, exp1, exp2, exp3, b[0], b[1]);
    if (lane == 0) *err_out = err;
}

int main() {
    float* d_err; CHECK(cudaMalloc(&d_err, 4));
    CHECK(cudaMemset(d_err, 0, 4));
    probe_kernel<<<1, 32>>>(d_err);
    CHECK(cudaDeviceSynchronize());
    float h_err; CHECK(cudaMemcpy(&h_err, d_err, 4, cudaMemcpyDeviceToHost));
    printf("PV MAX ERR = %g  %s\n", h_err, h_err < 1e-3 ? "PASS" : "FAIL");
    return 0;
}

